async function salvarEstadoMovePokemonPmp(token, numero, proposta) {
  const n = validarNumeroSlotMovePmp(numero);
  if (!token?.id || token.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') throw new Error('Selecione uma ficha de Pokémon.');
  if (!(await OBR.scene.isReady())) throw new Error('A cena do Owlbear não está pronta.');
  const presente = await pegarTokenAtualizado(token.id);
  if (!presente || presente.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') throw new Error('O Pokémon não está mais na cena.');
  const cadastrado = proposta.id ? moveCatalogoPmp(proposta.id) : null;
  if (proposta.id && !cadastrado) throw new Error('Golpe não encontrado no catálogo.');
  const max = Number.isInteger(cadastrado?.pp) ? cadastrado.pp : null;
  const ilimitado = cadastrado?.pp === "Ilimitado";
  const atual = ppInteiroLimitadoPmp(proposta.atual, max);
  const nome = cadastrado?.id || '';
  const patch = {
    [`${PREFIX}/golpe${n}CatalogoId`]: nome,
    [`${PREFIX}/golpe${n}Nome`]: nome,
    [`${PREFIX}/golpe${n}PPAtual`]: atual,
    [`${PREFIX}/golpe${n}PPMax`]: ilimitado ? "Ilimitado" : max
  };
  await OBR.scene.items.updateItems([token.id], (items) => {
    for (const item of items) {
      if (item.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') continue;
      Object.assign(item.metadata, patch);
    }
  });
  Object.assign(token.metadata, patch);
  return {
    id: nome,
    nome,
    max,
    ilimitado,
    atual,
    vantagem: presente.metadata?.[`${PREFIX}/golpe${n}VantagemDano`] === true || presente.metadata?.[`${PREFIX}/golpe${n}VantagemDano`] === 1 || presente.metadata?.[`${PREFIX}/golpe${n}VantagemDano`] === "1" || presente.metadata?.[`${PREFIX}/golpe${n}VantagemDano`] === "true"
  };
}
async function salvarVantagemMovePokemonPmp(token, numero, ativa) {
  const n = validarNumeroSlotMovePmp(numero);
  if (!token?.id || token.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') throw new Error('Selecione uma ficha de Pokémon.');
  if (!(await OBR.scene.isReady())) throw new Error('A cena do Owlbear não está pronta.');
  const presente = await pegarTokenAtualizado(token.id);
  if (!presente || presente.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') throw new Error('O Pokémon não está mais na cena.');
  const valor = !!ativa;
  const patch = { [`${PREFIX}/golpe${n}VantagemDano`]: valor };
  await OBR.scene.items.updateItems([token.id], (items) => {
    for (const item of items) {
      if (item.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') continue;
      Object.assign(item.metadata, patch);
    }
  });
  Object.assign(token.metadata, patch);
  return valor;
}
// Dados complementares provenientes dos JSONs originais do PokédexPMP.
function detalhesEstruturadosMovePmp(move) {
  if (!move) return '';
  const linhas = [];
  if (move.salvaguarda) linhas.push(`Salvaguarda: ${move.salvaguarda}`);
  if (move.cdBase !== undefined && move.cdBase !== null) linhas.push(`CD base: ${move.cdBase}`);
  if (move.dano && typeof move.dano === 'object') {
    const faixas = Object.entries(move.dano)
      .sort(([a],[b]) => Number(a) - Number(b))
      .map(([nivel,valor]) => {
        const qtd = Number(valor?.amount), faces = Number(valor?.dice_max);
        if (!Number.isFinite(qtd) || !Number.isFinite(faces)) return '';
        return `Nv ${nivel}: ${qtd}d${faces}${valor.move ? ' + MOVE' : ''}`;
      }).filter(Boolean);
    if (faixas.length) linhas.push(`Dados por nível: ${faixas.join(' · ')}`);
  }
  if (move.tabela && Array.isArray(move.tabela.Header) && Array.isArray(move.tabela.Rows)) {
    linhas.push('Tabela do Move:');
    linhas.push(move.tabela.Header.join(' | '));
    for (const linha of move.tabela.Rows) {
      if (Array.isArray(linha)) linhas.push(linha.join(' | '));
    }
  }
  return linhas.join('\n');
}
function ativarSeletorMovesPokemonPmp(token) {
  const el = (id) => document.getElementById(id);
  const overlay = el('golpesPmpOverlay'), busca = el('golpesPmpBusca');
  const resultados = el('golpesPmpResultados'), contador = el('golpesPmpContador');
  const mostrarMais = el('golpesPmpMais'), limpar = el('golpesPmpLimpar');
  const mensagem = el('golpesPmpMensagem'), titulo = el('golpesPmpTitulo');
  const fecharBotao = el('golpesPmpFechar');
  if (![overlay,busca,resultados,contador,mostrarMais,limpar,mensagem,titulo,fecharBotao].every(Boolean)) return;
  const painelInicial = el('golpe1NomeEscolhido');
  const estados = new Map(Array.from({length:5}, (_,i) => [i+1, estadoMovePokemonPmp(token, i+1)]));
  let numeroAtivo = null;
  let encontrados = POKEMON_MOVES_ORDENADOS;
  let limite = 45;
  let ocupado = false;
  const uiAtual = () => el('golpe1NomeEscolhido') === painelInicial;
  const renderizarSlot = (n) => {
    if (!uiAtual()) return;
    const estado = estados.get(n);
    const info = estado.id ? POKEMON_MOVES_POR_ID.get(estado.id) : null;
    const campoNome = el(`golpe${n}Nome`), nome = el(`golpe${n}NomeEscolhido`);
    const resumo = el(`golpe${n}Resumo`), descricao = el(`golpe${n}Descricao`);
    const ppValor = el(`golpe${n}PPValor`), menos = el(`golpe${n}PPMenos`);
    const mais = el(`golpe${n}PPMais`), vantagem = el(`golpe${n}Vantagem`);
    const aviso = el(`golpe${n}PPAviso`), lupa = el(`golpe${n}AbrirPesquisa`);
    if (![campoNome,nome,resumo,descricao,ppValor,menos,mais,vantagem,aviso,lupa].every(Boolean)) return;
    campoNome.value = estado.nome;
    resumo.textContent = estado.nome || `Move ${n}`;
    nome.textContent = estado.nome ? `${estado.nome} ${descricao.hidden ? '▾' : '▴'}` : '🔎 Pesquisar golpe';
    nome.setAttribute('aria-expanded', String(!descricao.hidden));
    ppValor.textContent = estado.ilimitado ? "∞" : `${estado.atual === null ? '—' : estado.atual} / ${estado.max === null ? '—' : estado.max}`;
    const temPp = !!info && Number.isInteger(estado.max);
    menos.disabled = ocupado || !temPp || estado.atual <= 0;
    mais.disabled = ocupado || !temPp || estado.atual >= estado.max;
    vantagem.checked = !!estado.vantagem;
    vantagem.disabled = ocupado;
    nome.disabled = ocupado;
    lupa.disabled = ocupado;
    aviso.textContent = !estado.nome ? 'Pesquise um golpe.' : !info ? 'Golpe personalizado antigo: use a lupa para encontrar no catálogo.' : estado.ilimitado ? 'PP ilimitado; não é necessário gastar PP.' : !temPp ? 'Este golpe não possui PP definido no catálogo.' : '';
    if (!descricao.hidden) {
      el(`golpe${n}DescricaoTitulo`).textContent = info?.nome || estado.nome || '';
      el(`golpe${n}DescricaoDados`).textContent = info ? [`Tipo: ${info.tipo || '—'}`, `PP: ${info.pp ?? 'não definido'}`, `Tempo: ${info.tempo || '—'}`, `Alcance: ${info.alcance || '—'}`, `Duração: ${info.duracao || '—'}`].join(' · ') : '';
      el(`golpe${n}DescricaoTexto`).textContent = info?.descricao || 'Golpe anterior à biblioteca. Use a lupa para selecionar o golpe oficial.';
      el(`golpe${n}DescricaoProgresso`).textContent = [info?.progressao ? `Progressão: ${info.progressao}` : '', detalhesEstruturadosMovePmp(info)].filter(Boolean).join('\n\n');
    }
  };
  const renderizarTodos = () => {for(let n=1;n<=5;n++) renderizarSlot(n);};
  const fechar = (forcar=false) => {
    if (ocupado && !forcar) return;
    overlay.classList.remove('aberto');
    overlay.setAttribute('aria-hidden','true');
    if (numeroAtivo !== null) el(`golpe${numeroAtivo}AbrirPesquisa`)?.focus();
  };
  const renderizarResultados = () => {
    resultados.innerHTML = encontrados.slice(0, limite).map((move) => {
      const indice = POKEMON_MOVES_ORDENADOS.indexOf(move);
      return `<button type="button" class="pmpMovesResultado" role="option" aria-selected="${estados.get(numeroAtivo)?.id === move.id}"
        data-move-indice="${indice}"><strong>${esc(move.id)}</strong><span style="display:block;font-size:10px;font-weight:500;color:#59677e;">${esc(move.nome !== move.id ? move.nome : move.tipo)} · PP ${move.pp ?? '—'}</span></button>`;
    }).join('') || '<p style="margin:8px!important">Nenhum golpe encontrado.</p>';
    contador.textContent = `${encontrados.length} resultado(s) entre ${POKEMON_MOVES_CATALOGO.length} golpes`;
    mostrarMais.style.display = encontrados.length > limite ? '' : 'none';
    limpar.disabled = ocupado || !estados.get(numeroAtivo)?.nome;
  };
  const filtrar = () => {
    const termo = normalizarBuscaMovePmp(busca.value);
    encontrados = POKEMON_MOVES_ORDENADOS.filter((move) => POKEMON_MOVES_TEXTO_BUSCA.get(move.id).includes(termo));
    limite = 45;
    resultados.scrollTop = 0;
    renderizarResultados();
  };
  const persistir = async (n, proposta, textoSucesso, encerrarModal=false) => {
    if (ocupado || !uiAtual()) return;
    ocupado = true;
    renderizarTodos();
    mostrarMais.disabled = true;
    busca.disabled = true;
    mensagem.textContent = `Salvando Move ${n}...`;
    try {
      const anterior = estados.get(n);
      const novoEstado = await salvarEstadoMovePokemonPmp(token, n, proposta);
      estados.set(n, { ...anterior, ...novoEstado, vantagem: (novoEstado.vantagem ?? anterior?.vantagem ?? false) });
      if (uiAtual()) {
        el(`golpe${n}Descricao`).hidden = true;
        if (encerrarModal) fechar(true);
        mensagem.textContent = textoSucesso;
        const aviso = el(`golpe${n}PPAviso`);
        if (aviso) aviso.textContent = textoSucesso;
      }
    } catch (erro) {
      console.error(`Não foi possível salvar Move ${n}:`, erro);
      mensagem.textContent = `Erro: ${erro?.message || String(erro)}`;
      const aviso = el(`golpe${n}PPAviso`);
      if (aviso) aviso.textContent = mensagem.textContent;
    } finally {
      ocupado = false;
      busca.disabled = false;
      mostrarMais.disabled = false;
      if (uiAtual()) {renderizarTodos(); if (numeroAtivo !== null) renderizarResultados();}
    }
  };
  for(let n=1;n<=5;n++) {
    const nome = el(`golpe${n}NomeEscolhido`), lupa = el(`golpe${n}AbrirPesquisa`);
    const descricao = el(`golpe${n}Descricao`);
    if (![nome,lupa,descricao].every(Boolean)) continue;
    nome.addEventListener('click', () => {
      if(ocupado) return;
      if(!estados.get(n).nome) {lupa.click();return;}
      descricao.hidden = !descricao.hidden;
      renderizarSlot(n);
    });
    lupa.addEventListener('click', () => {
      if(ocupado) return;
      numeroAtivo = n;
      titulo.textContent = `🔎 Escolher Move ${n}`;
      overlay.classList.add('aberto');
      overlay.setAttribute('aria-hidden','false');
      busca.value='';
      mensagem.textContent = `Selecione um golpe para o Move ${n}.`;
      filtrar();
      busca.focus();
    });
    el(`golpe${n}PPMenos`)?.addEventListener('click', () => {
      const e=estados.get(n);if(Number.isInteger(e.max)) persistir(n,{id:e.id,atual:e.atual-1},'PP reduzido.');
    });
    el(`golpe${n}PPMais`)?.addEventListener('click', () => {
      const e=estados.get(n);if(Number.isInteger(e.max)) persistir(n,{id:e.id,atual:e.atual+1},'PP recuperado.');
    });
    el(`golpe${n}Vantagem`)?.addEventListener('change', async (evento) => {
      if (ocupado || !uiAtual()) return;
      const marcado = !!evento.currentTarget?.checked;
      ocupado = true;
      renderizarTodos();
      mostrarMais.disabled = true;
      busca.disabled = true;
      mensagem.textContent = `Salvando Vant do Move ${n}...`;
      try {
        const valor = await salvarVantagemMovePokemonPmp(token, n, marcado);
        const atual = estados.get(n) || estadoMovePokemonPmp(token, n);
        estados.set(n, { ...atual, vantagem: valor });
        mensagem.textContent = valor ? `✓ Vant ativada no Move ${n}.` : `✓ Vant desativada no Move ${n}.`;
      } catch (erro) {
        console.error(`Não foi possível salvar a Vant do Move ${n}:`, erro);
        mensagem.textContent = `Erro: ${erro?.message || String(erro)}`;
      } finally {
        ocupado = false;
        busca.disabled = false;
        mostrarMais.disabled = false;
        if (uiAtual()) {renderizarTodos(); if (numeroAtivo !== null) renderizarResultados();}
      }
    });
  }
  fecharBotao.addEventListener('click', () => fechar());
  overlay.addEventListener('click', (evento) => {if(evento.target===overlay) fechar();});
  busca.addEventListener('input', filtrar);
  busca.addEventListener('keydown', (evento) => {
    if(evento.key==='Escape'){evento.preventDefault();fechar();}
    if(evento.key==='Enter'){
      const primeiro=resultados.querySelector('[data-move-indice]');
      if(primeiro){evento.preventDefault();primeiro.click();}
    }
  });
  mostrarMais.addEventListener('click', () => {limite+=45;renderizarResultados();});
  resultados.addEventListener('click', (evento) => {
    const botao=evento.target.closest('[data-move-indice]');
    if(!botao || ocupado || numeroAtivo===null) return;
    const indice=Number(botao.dataset.moveIndice);
    const escolhido=POKEMON_MOVES_ORDENADOS[indice];
    if(!Number.isInteger(indice) || !escolhido) return;
    const mesmo=estados.get(numeroAtivo).id===escolhido.id;
    persistir(numeroAtivo,{id:escolhido.id,atual:mesmo ? estados.get(numeroAtivo).atual : escolhido.pp},`✓ ${escolhido.id} selecionado.`,true);
  });
  limpar.addEventListener('click', () => {
    if(numeroAtivo!==null) persistir(numeroAtivo,{id:'',atual:null},`Move ${numeroAtivo} removido.`,true);
  });
  renderizarTodos();
}
