const META_POKEMON_ESPECIE = `${PREFIX}/pokemon-especie`;
const POKEDEX_ATRIBUTOS_PMP = Object.freeze(['for','des','con','int','sab','car']);
const POKEDEX_ESPECIES_POR_NOME = new Map(POKEDEX_ESPECIES_PMP.map((r) => [r[0], r]));

function normalizarBuscaPokedexPmp(texto) {
  return String(texto ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Substitui apenas o status solicitado; não altera imagem, golpes, itens,
// movimentos, vínculo ao treinador, condições, perícias nem nome/apelido.
function aplicarEspeciePokemonLv1NaFicha(metadata, especie) {
  if (!metadata || typeof metadata !== 'object') throw new Error('Ficha sem metadados.');
  if (!Array.isArray(especie) || especie.length !== 10 || !POKEDEX_ESPECIES_POR_NOME.has(especie[0])) {
    throw new Error('Espécie não cadastrada na PokédexPMP.');
  }
  const [nome, numero, hp, ca, ...atributos] = especie;
  if (![hp,ca,...atributos].every((valor) => Number.isFinite(valor))) {
    throw new Error(`Dados inválidos no registro de ${nome}.`);
  }
  metadata[META_POKEMON_ESPECIE] = nome;
  metadata[`${PREFIX}/hpAtual`] = hp;
  metadata[`${PREFIX}/hpMax`] = hp;
  metadata[`${PREFIX}/ca`] = ca;
  metadata[`${PREFIX}/pokemon-level`] = 1;
  POKEDEX_ATRIBUTOS_PMP.forEach((atributo, indice) => {
    const valor = atributos[indice];
    metadata[`${PREFIX}/status-${atributo}`] = valor;
    metadata[`${PREFIX}/mod-${atributo}`] = formatarBonus(modificadorPorStatus(valor));
  });
  // Regenerar os valores a partir da base da espécie e aplicar a Nature UMA vez.
  // O marcador já aplicado poderia bloquear a Nature, e não resetá-lo duplicaria
  // os efeitos. Esta ordem mantém a operação idempotente, inclusive em cópias.
  const nature = metadata[META_SELVAGEM_NATURE];
  if (nature && typeof nature === 'object') {
    delete metadata[`${PREFIX}/selvagem-nature-aplicada`];
    aplicarNatureSelvagem(metadata, nature);
  }
}

async function preencherEspeciePokemonNoToken(token, nomeEspecie) {
  const especie = POKEDEX_ESPECIES_POR_NOME.get(String(nomeEspecie || ''));
  if (!especie) throw new Error('A espécie escolhida não está na Pokédex.');
  if (!token?.id || token.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') {
    throw new Error('Selecione um token com ficha de Pokémon.');
  }
  if (!(await OBR.scene.isReady())) throw new Error('A cena não está pronta.');
  // Espera operações já encaminhadas para evitar gravações fora de ordem.
  await salvamentoBuffPendente.catch(() => {});
  await salvamentoMovimentoPendente.catch(() => {});
  const presente = await pegarTokenAtualizado(token.id);
  if (!presente || presente.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') {
    throw new Error('Este Pokémon não está mais na cena.');
  }
  await OBR.scene.items.updateItems([token.id], (items) => {
    for (const item of items) {
      if (item.metadata?.[`${PREFIX}/tipoFicha`] !== 'pokemon') continue;
      aplicarEspeciePokemonLv1NaFicha(item.metadata, especie);
    }
  });
  const atualizado = await pegarTokenAtualizado(token.id);
  if (!atualizado || atualizado.metadata?.[META_POKEMON_ESPECIE] !== especie[0]) {
    throw new Error('Não foi possível confirmar o salvamento da espécie.');
  }
  // Usa o HUD incremental/antiduplicação já existente; não cria outro token.
  // Uma falha visual não desfaz os dados da ficha que já foram salvos.
  let avisoHud = '';
  try {
    const m = atualizado.metadata;
    const evasao = normalizarEstagioBuff(m[`${PREFIX}/buff-evas`] ?? 0, 'evas');
    const caFinal = Number(m[`${PREFIX}/ca`] ?? 10) + evasao + bonusCaMegaDoToken(atualizado);
    await criarStatusNoToken(atualizado, Number(m[`${PREFIX}/hpAtual`]),
      Number(m[`${PREFIX}/hpMax`]), caFinal);
  } catch (erro) {
    console.warn('Espécie salva, mas não foi possível atualizar o HUD:', erro);
    avisoHud = ' Espécie salva; revise o HUD na ficha do mestre.';
  }
  return { token: atualizado, avisoHud };
}

